<?php
require __DIR__ . '/config.php';
require_role('admin');
$pageTitle = 'Laporan Transaksi';
$from = $_GET['from'] ?? date('Y-m-01');
$to = $_GET['to'] ?? date('Y-m-d');
$status = $_GET['status'] ?? 'all';
$validDate = static function ($value) { $d = DateTime::createFromFormat('!Y-m-d', (string)$value); return $d && $d->format('Y-m-d') === $value; };
if (!$validDate($from) || !$validDate($to) || $from > $to) { $from = date('Y-m-01'); $to = date('Y-m-d'); }
$where = 'WHERE DATE(p.created_at) BETWEEN ? AND ?';
$params = [$from, $to];
if (in_array($status, ['pending', 'paid', 'rejected', 'failed', 'expire'], true)) { $where .= ' AND p.status = ?'; $params[] = $status; } else { $status = 'all'; }
$sql = "SELECT p.*, u.full_name, s.student_no, s.class_level, fc.name AS category FROM payments p JOIN students s ON s.id = p.student_id JOIN users u ON u.id = s.user_id JOIN fee_categories fc ON fc.id = p.fee_category_id $where ORDER BY p.created_at DESC";
$stmt = $pdo->prepare($sql); $stmt->execute($params); $rows = $stmt->fetchAll();
$totalAmount = 0; $paidAmount = 0; $paidCount = 0;
foreach ($rows as $row) { $totalAmount += (float)$row['total_amount']; if ($row['status'] === 'paid') { $paidAmount += (float)$row['total_amount']; $paidCount++; } }
require __DIR__ . '/includes/header.php';
$statusLabels = ['all' => 'Semua status', 'pending' => 'Menunggu', 'paid' => 'Lunas', 'rejected' => 'Ditolak', 'failed' => 'Gagal', 'expire' => 'Kedaluwarsa'];
$methodLabels = ['cash' => 'Tunai', 'bank_transfer' => 'Transfer Bank', 'midtrans' => 'Midtrans'];
?>
<section class="card no-print"><div class="section-head"><div><h2>Filter laporan</h2><p>Pilih rentang tanggal dan status untuk membuat laporan transaksi.</p></div><button class="btn" onclick="window.print()">⎙ Cetak / Simpan PDF</button></div>
<form method="get" class="report-filter"><div class="form-group"><label>Dari tanggal</label><input class="input" type="date" name="from" value="<?= e($from) ?>" required></div><div class="form-group"><label>Sampai tanggal</label><input class="input" type="date" name="to" value="<?= e($to) ?>" required></div><div class="form-group"><label>Status transaksi</label><select name="status"><?php foreach ($statusLabels as $key => $label): ?><option value="<?= e($key) ?>" <?= $status === $key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="form-group report-action"><label>&nbsp;</label><button class="btn" type="submit">Tampilkan laporan</button></div></form></section>
<div class="report-print-head"><div class="report-brand"><div class="report-logo">MH</div><div><h2>PONDOK PESANTREN MAMBAUL HUDA</h2><p>Laporan Administrasi Keuangan</p></div></div><div class="report-period"><small>PERIODE LAPORAN</small><strong><?= e(date('d/m/Y', strtotime($from))) ?> — <?= e(date('d/m/Y', strtotime($to))) ?></strong><span><?= e($statusLabels[$status]) ?></span></div></div>
<div class="report-stats"><div class="report-stat"><small>JUMLAH TRANSAKSI</small><strong><?= count($rows) ?></strong><span>Transaksi pada periode</span></div><div class="report-stat"><small>TOTAL NOMINAL</small><strong><?= rupiah($totalAmount) ?></strong><span>Semua status yang dipilih</span></div><div class="report-stat"><small>TRANSAKSI LUNAS</small><strong><?= $paidCount ?></strong><span>Transaksi terverifikasi</span></div><div class="report-stat"><small>NOMINAL LUNAS</small><strong><?= rupiah($paidAmount) ?></strong><span>Penerimaan yang telah lunas</span></div></div>
<section class="card report-table-card"><div class="section-head"><div><h2>Rincian transaksi</h2><p><?= count($rows) ?> baris data · Diurutkan dari transaksi terbaru</p></div><span class="pill">Dicetak <?= date('d/m/Y H:i') ?></span></div><div class="table-wrap"><table class="report-table"><thead><tr><th>No.</th><th>Tanggal</th><th>Nama santri</th><th>No. induk</th><th>Jenjang</th><th>Periode SPP</th><th>Metode</th><th>Status</th><th class="align-right">Nominal</th></tr></thead><tbody>
<?php foreach ($rows as $i => $row): ?><tr><td><?= $i + 1 ?></td><td><?= e(date('d/m/Y H:i', strtotime($row['created_at']))) ?></td><td><strong><?= e($row['full_name']) ?></strong><small class="table-sub"><?= e($row['order_id']) ?></small></td><td><?= e($row['student_no']) ?></td><td><?= e($row['class_level']) ?></td><td><?= e(month_label($row['billing_month'])) ?><small class="table-sub"><?= e($row['category']) ?></small></td><td><?= e($methodLabels[$row['method']] ?? $row['method']) ?></td><td><span class="report-status status-<?= e($row['status']) ?>"><?= e(ucfirst($row['status'])) ?></span></td><td class="align-right amount-cell"><?= rupiah($row['total_amount']) ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="9" class="empty">Tidak ada transaksi pada periode dan filter yang dipilih.</td></tr><?php endif; ?></tbody><tfoot><tr><td colspan="8">TOTAL NOMINAL TRANSAKSI</td><td class="align-right"><?= rupiah($totalAmount) ?></td></tr></tfoot></table></div></section>
<div class="report-signature"><div><span>Mengetahui,</span><strong>Pimpinan Pesantren</strong><div class="signature-space"></div><b>( ................................ )</b></div><div><span><?= e('Bagian Keuangan') ?></span><strong>Petugas Administrasi</strong><div class="signature-space"></div><b>( ................................ )</b></div></div>
